                                  lcd.print(" NAME:              ");

                                    Serial.println();
                                      Serial.println("================================");
                                        Serial.println("      RFID SECURITY LOCK");
                                          Serial.println("================================");
                                            Serial.println("Enter Card Number:");
                                              Serial.println("Press ENTER to CHECK");
                                                Serial.println();
                                                }

                                                void loop()
                                                {
                                                  // Check incoming characters
