                                                                                                                // Clear card number after checking
                                                                                                                        id = "";

                                                                                                                                Serial.println();
                                                                                                                                        Serial.println("--------------------------------");
                                                                                                                                                Serial.println("Enter Card Number:");
                                                                                                                                                        Serial.println("Press ENTER to CHECK");
                                                                                                                                                                Serial.println("--------------------------------");
                                                                                                                                                                      }
                                                                                                                                                                          }

                                                                                                                                                                              // --------------------------------
                                                                                                                                                                                  // BACKSPACE
                                                                                                                                                                                      // --------------------------------
                                                                                                                                                                                          else if (c == 8)
                                                                                                                                                                                              {
                                                                                                                                                                                                    if (id.length() > 0)
                                                                                                                                                                                                          {
                                                                                                                                                                                                                  id.remove(id.length() - 1);
                                                                                                                                                                                                                        }
                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                // --------------------------------
                                                                                                                                                                                                                                    // NORMAL CHARACTER
                                                                                                                                                                                                                                        // --------------------------------
                                                                                                                                                                                                                                            else
                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                      // Add character to card number
                                                                                                                                                                                                                                                            id += c;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                  }


